/**
 * A running profile on the iPhone.
 */
public protocol MobileSessionProtocol : AnyObject {
    
    /**
     * A link opened. `budget` is the largest write in bytes; `rssi` the
     * signal strength when known.
     */
    func bleConnected(link: String, budget: UInt32, rssi: Int16?, now: UInt64) 
    
    func bleDisconnected(link: String) 
    
    /**
     * Bytes a link received (one GATT write or notification).
     */
    func bleReceived(link: String, bytes: Data, now: UInt64) 
    
    /**
     * A signal strength reading of a link, for distance.
     */
    func bleRssi(link: String, rssi: Int16, now: UInt64) 
    
    /**
     * Bluetooth is on: Shum-Core's mesh starts for this profile. Until
     * then `ble` effects carry whole packets for the app's own Bluetooth.
     */
    func bleStart(now: UInt64) throws 
    
    /**
     * Bluetooth is off: everyone nearby is gone.
     */
    func bleStop() 
    
    /**
     * Bluetooth state for snapshots: `role` is "scan" or "advertise".
     */
    func bluetooth(role: String, state: String) 
    
    func closed(relay: UInt32, attempt: UInt64, now: UInt64) 
    
    /**
     * What Swift does now, in order, as a JSON array of `{"type": …}`:
     * `connect` (relay, attempt), `send` (relay, text), `ping` (relay),
     * `close` (relay); news `connected`, `disconnected`, `eose` (url);
     * `renamed` (name); `reply` (id, ok or error); `push` (event, path,
     * headers, body in base64) to POST to the push service; `ble-frames`
     * (link, frames in base64) for the radio to write while Shum-Core's mesh
     * runs, or `ble` (peer, packet bytes in base64) for the app's own
     * Bluetooth before it does.
     */
    func effects(now: UInt64)  -> String
    
    /**
     * Someone nearby went out of reach.
     */
    func nearbyGone(routing: String) 
    
    /**
     * A Shum packet (its JSON bytes) arrived over Bluetooth from `routing`,
     * whose Noise session key is `noise`.
     */
    func nearbyPacket(routing: String, noise: Data, packet: Data) throws 
    
    /**
     * Someone nearby over Bluetooth: their routing ID, signed card (JSON),
     * Noise session key, estimated distance in metres and whether the link
     * is direct. The session records the encounter and can deliver to them.
     */
    func nearbyPeer(routing: String, card: String, noise: Data, distance: UInt32?, direct: Bool) throws 
    
    /**
     * Grows when someone comes or goes nearby or their distance changes,
     * which stores nothing; Swift then reads `snapshot()` alone.
     */
    func nearbyRevision()  -> UInt64
    
    func opened(relay: UInt32, attempt: UInt64, now: UInt64) 
    
    /**
     * The push service answered for `event`; `error` says why it failed.
     */
    func pushed(event: String, error: String?) 
    
    func received(relay: UInt32, attempt: UInt64, text: String, now: UInt64) 
    
    /**
     * Handles a request given as JSON. Returns `{"ok": …}` or
     * `{"error": …}` at once, or nothing when the answer comes later as a
     * `reply` effect with this `id`.
     */
    func request(id: UInt64, request: String, now: UInt64)  -> String?
    
    /**
     * Grows with every change to the stored state; Swift reads `state()`
     * again only when it did.
     */
    func revision()  -> UInt64
    
    func snapshot()  -> String
    
    /**
     * The stored profile state (protocol section 09) as JSON, the same
     * layout the iOS app decodes into its own model.
     */
    func state()  -> String
    
    /**
     * Call about once a second.
     */
    func tick(now: UInt64) 
    
    func url(relay: UInt32)  -> String?
    
    /**
     * The app is back in the foreground, or a push woke it: relays
     * reconnect at once.
     */
    func wake(now: UInt64) 
    
}

